mapper.select:
select
*
from T_MDM_MATERIAL_INFO
where PRODUCT_TYPE_NAME = #{productTypeName,jdbcType=VARCHAR}
          AND MATERIAL_CODE IN (SELECT MATERIAL_CODE FROM T_RECEIVE_MAIN_PLAN WHERE YEAR = #{year} AND MONTH =
      #{month}
  AND VERSION = #{planVersion}
  AND PRODUCT_TYPE_NAME = #{productTypeName})

SELECT tmpi.ID, tmpi.FACTORY_CODE, tmpi.MATERIAL_CODE, mmmr.MOULD_NO, mmmr.SPEC_CODE, mmmr.MOULD_NUMBER, mmpc.EMBRYO_CODE, mmpc.CONSTRUCTION_SPEC_CODE, mmpc.CONSTRUCTION_CODE, tmpi.PRODUCT_DESC, tmpi.PRO_SIZE, tmpi.PRODUCT_TYPE_CODE, tmpi.PRODUCT_TYPE_NAME, tmpi.MOULD_CATEGORY, tmpi.SPECIFICATIONS, tmpi.PATTERN, tmpi.BRAND, tmpi.TIRE_TYPE, tmpi.COMMON_TYPE, tmpi.HIERARCHY, tmpi.REPLACE_GROUP, tmpi.CANT_PRODUCE, tmpi.NO_DELIVERY, tmpi.SPEED, tmpi.ABILITY, tmpi.ENVIRONMENT_PROTECTION, tmpi.AUTHENTICATION, tmpi.MATERIAL_GROUP_CODE, tmpi.FORBID_TAG, tmpi.SINGLE_TIRE_WEIGHT, tmpi.MOULD_CLAMPING_PRESSURE, tmpi.GROSS_RATE_JSON, tmpi.REMARK, tmpi.IS_DELETE, tmpi.CREATE_TIME, tmpi.UPDATE_TIME, tmpi.CREATE_BY, tmpi.UPDATE_BY FROM t_mdm_material_info tmpi LEFT JOIN (SELECT mpmr.FACTORY_CODE, mpmr.MATERIAL_CODE, GROUP_CONCAT( DISTINCT(tmmi.MOULD_NO) ) AS MOULD_NO, GROUP_CONCAT( DISTINCT(mpmr.SPEC_CODE) ) AS SPEC_CODE, COUNT( DISTINCT(tmmi.MOULD_CODE) ) AS MOULD_NUMBER FROM t_mdm_product_model_relation mpmr LEFT JOIN t_mdm_model_info tmmi ON tmmi.MOULD_CODE = mpmr.MOULD_CODE AND tmmi.FACTORY_CODE = mpmr.FACTORY_CODE WHERE 1=1
AND mpmr.FACTORY_CODE = #{factoryCode}
GROUP BY mpmr.FACTORY_CODE, mpmr.MATERIAL_CODE ) mmmr ON tmpi.FACTORY_CODE = mmmr.FACTORY_CODE AND tmpi.MATERIAL_CODE = mmmr.MATERIAL_CODE LEFT JOIN(SELECT tmpc.FACTORY_CODE, tmpc.MATERIAL_CODE, GROUP_CONCAT( DISTINCT(tmpc.EMBRYO_CODE) ) AS EMBRYO_CODE, GROUP_CONCAT( DISTINCT(tmpc.SPEC_CODE) ) AS CONSTRUCTION_SPEC_CODE, GROUP_CONCAT( DISTINCT(tmpc.CONSTRUCTION_CODE) ) AS CONSTRUCTION_CODE FROM t_mdm_product_construction tmpc WHERE IFNULL(tmpc.IS_DELETE,0) = 0
AND tmpc.FACTORY_CODE = #{factoryCode}
GROUP BY tmpc.FACTORY_CODE, tmpc.MATERIAL_CODE ) mmpc ON tmpi.FACTORY_CODE = mmpc.FACTORY_CODE AND tmpi.MATERIAL_CODE = mmpc.MATERIAL_CODE WHERE tmpi.IS_DELETE = 0
AND tmpi.FACTORY_CODE = #{factoryCode}
AND tmpi.MATERIAL_CODE = #{materialCode}
AND tmpi.PRODUCT_DESC = #{productDesc}
AND tmpi.SPECIFICATIONS LIKE #{specifications} || '%'
AND tmpi.PATTERN LIKE #{pattern} || '%'
AND tmpi.BRAND = #{brand}
AND tmpi.TIRE_TYPE = #{tireType}
AND tmpi.COMMON_TYPE = #{commonType}
AND mmpc.EMBRYO_CODE LIKE CONCAT(#{embryoCode}, '%')
AND mmmr.MOULD_NO LIKE CONCAT(#{mouldNo}, '%')
AND (tmpi.TIRE_TYPE IS NULL OR tmpi.TIRE_TYPE = '')
AND (mmmr.MOULD_NO IS NULL OR mmmr.MOULD_NO = '')
AND (tmpi.COMMON_TYPE IS NULL OR tmpi.COMMON_TYPE = '')
AND (tmpi.BRAND IS NULL OR tmpi.BRAND = '')
AND (mmpc.EMBRYO_CODE IS NULL OR mmpc.EMBRYO_CODE = '')
